def f(inp):
    g=[r[:] for r in inp]; h,w=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    shape=[v for v in Counter(x for r in g for x in r) if v!=bg]
    sc=shape[0] if shape else None
    out=[r[:] for r in g]
    def walk(r,c,dr,dc):
        # step until non-scene color or off-grid
        while True:
            nr,nc=r+dr, c+dc
            if not(0<=nr<h and 0<=nc<w): return None
            if g[nr][nc]!=sc: return g[nr][nc]
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg: continue
            if (walk(r,c,-1,0)==sc and walk(r,c,1,0)==sc) or (walk(r,c,0,-1)==sc and walk(r,c,0,1)==sc):
                out[r][c]=4
    return out
