        others=[v for v,k in sorted(counts.items()) if v!=bgl]
        if others: bgl,others[others.index(min(others,key=lambda v:counts[v]))]
        oth=others[0]
    # flood fill through bg from border; mark bg cells NOT reachable = enclosed -> change to 4
